    piegamenti_bars: { nome: "Piegamenti con push-up bars", consigli: ["Impugna le maniglie con i polsi dritti.", "Scendi un po' più in basso del normale, senza forzare le spalle.", "Corpo in linea dall'inizio alla fine."], errori: ["Maniglie su una superficie che scivola.", "Scendere troppo perdendo il controllo."], respiro: "Inspira in discesa, espira in spinta." },
