    lat_elastico: { nome: "Lat machine con elastico", consigli: ["Fissa l'elastico in alto, per esempio sopra una porta chiusa.", "In ginocchio o seduto, braccia tese verso l'alto.", "Tira i gomiti in basso verso i fianchi."], errori: ["Piegarsi all'indietro.", "Usare solo le braccia senza abbassare le spalle."], respiro: "Espira tirando in basso, inspira tornando su." },
