    squat: { nome: "Squat", consigli: ["Piedi larghi come le spalle, punte un po' in fuori.", "Scendi finché le cosce sono parallele al pavimento.", "Petto alto, peso sui talloni."], errori: ["Talloni che si sollevano.", "Ginocchia verso l'interno."], respiro: "Inspira scendendo, espira salendo." },
