    burpees_senza_salto: { nome: "Burpees senza salto", consigli: ["Mani a terra, porta indietro un piede alla volta fino al plank.", "Torna avanti un piede alla volta.", "Alzati in piedi del tutto."], errori: ["Bacino che cade nel plank.", "Schiena curva nel rialzarsi."], respiro: "Espira alzandoti, inspira scendendo." },
