    salto_corda: { nome: "Salto con la corda", consigli: ["Salti bassi, sugli avampiedi.", "Gira la corda con i polsi, non con le spalle.", "Gomiti vicini ai fianchi."], errori: ["Saltare troppo in alto.", "Atterrare sui talloni."], respiro: "Respira a ritmo regolare." },
    cat_cow: { nome: "Cat-cow", consigli: ["A quattro zampe, mani sotto le spalle.", "Inarca la schiena guardando avanti, poi incurvala guardando l'ombelico.", "Movimento lento e continuo."], errori: ["Muovere solo il collo.", "Andare di fretta."], respiro: "Inspira inarcando, espira incurvando." },
